function.arguments:
{"command": "# Test better certificate extraction
CHAIN_PATH="/app/signed/app.bin.chain.pem"
SIGNING_CERT=$(mktemp)

awk '
BEGIN { in_cert = 0; cert = "" }
/^-----BEGIN CERTIFICATE-----/ { in_cert = 1; cert = $0; next }
in_cert { 
  cert = cert "\n" $0
  if (/^-----END CERTIFICATE-----/) { 
    print cert
    in_cert = 0 
  }
}
' "$CHAIN_PATH" > "$SIGNING_CERT"

echo "Lines in extracted cert:"
wc -l "$SIGNING_CERT"
echo ""
echo "Subject:"
openssl x509 -in "$SIGNING_CERT" -noout -subject 2>/dev/null
echo ""
echo "Issuer:"
openssl x509 -in "$SIGNING_CERT" -noout -issuer 2>/dev/null
rm -f "$SIGNING_CERT""}
